				var line = "calc(" + spec[5].replace("$S", String(s)) + ")";
				out[name] = { size: size, line: line };
				decls.push("--dsw-font-markdown-" + name + ": " + (italic ? "italic " : "") + (weight ? weight + " " : "") + size + "/" + line + " " + family + ";");
